package com.lexorion.payroll.api;
import static com.lexorion.payroll.api.SalaryTemplateDtos.*;import com.lexorion.payroll.api.CompensationDtos.ProfileResponse;import com.lexorion.payroll.service.SalaryTemplateService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/payroll/salary-templates")@PreAuthorize("hasRole('ADMIN')")public class SalaryTemplateController{private final SalaryTemplateService service;public SalaryTemplateController(SalaryTemplateService s){service=s;}@GetMapping public java.util.List<SalaryTemplateResponse>list(){return service.list();}@PostMapping public ResponseEntity<SalaryTemplateResponse>create(@Valid@RequestBody CreateSalaryTemplate r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@GetMapping("/{templateKey}")public SalaryTemplateResponse get(@PathVariable String templateKey){return service.get(templateKey);}@PatchMapping("/{templateKey}")public SalaryTemplateResponse update(@PathVariable String templateKey,@Valid@RequestBody UpdateSalaryTemplate r){return service.update(templateKey,r);}@DeleteMapping("/{templateKey}")public SalaryTemplateResponse deactivate(@PathVariable String templateKey){return service.deactivate(templateKey);}@PostMapping("/{templateKey}/employees/{employeeCode}/compensation")public ResponseEntity<ProfileResponse>assign(@PathVariable String templateKey,@PathVariable String employeeCode,@Valid@RequestBody AssignSalaryTemplate r){return ResponseEntity.status(HttpStatus.CREATED).body(service.assign(templateKey,employeeCode,r));}}
